public static class VoxelBenchmarkDashboard
{
	public const int Version = 3;

	public static string Build( string historyJsonLines )
	{
		var rows = string.Join( ",", (historyJsonLines ?? string.Empty)
			.Split( '\n', System.StringSplitOptions.RemoveEmptyEntries | System.StringSplitOptions.TrimEntries )
			.Select( line => line.Replace( "</", "<\\/", System.StringComparison.Ordinal ) ) );
		return Template.Replace( "/*__VOXEL_BENCHMARK_ROWS__*/", rows, System.StringComparison.Ordinal );
	}

	private const string Template = """
<!doctype html>
<html lang="en" data-dashboard-version="3">
<head>
	<meta charset="utf-8">
	<meta name="viewport" content="width=device-width,initial-scale=1">
	<title>Voxel Terrain Performance</title>
	<style>
		:root{color-scheme:dark;--bg:#091019;--panel:#111c29;--panel2:#162434;--line:#26384d;--text:#edf4fc;--muted:#94a8bd;--good:#58d391;--warn:#ffc766;--bad:#ff727c;--info:#65a9ff;--purple:#c18cff;--cyan:#5ed5dc;--shadow:0 14px 38px #0005}
		*{box-sizing:border-box}body{margin:0;background:radial-gradient(circle at 8% -10%,#193454 0,transparent 34rem),var(--bg);color:var(--text);font:14px/1.45 Inter,ui-sans-serif,system-ui,-apple-system,"Segoe UI",sans-serif}button,select,input{font:inherit}button,select,input{color:var(--text);background:#0d1722;border:1px solid #344b64;border-radius:8px;padding:8px 10px}button{cursor:pointer}button:hover{border-color:#6d8dab;background:#142334}button:focus-visible,select:focus-visible,input:focus-visible{outline:2px solid var(--info);outline-offset:2px}.shell{width:min(1560px,calc(100% - 36px));margin:auto}.topbar{position:sticky;top:0;z-index:20;background:#091019eF;backdrop-filter:blur(14px);border-bottom:1px solid var(--line)}.toprow{min-height:74px;display:flex;align-items:center;gap:16px}.brand{display:flex;align-items:center;gap:12px;min-width:280px}.mark{width:38px;height:38px;border-radius:11px;display:grid;place-items:center;background:linear-gradient(145deg,#3187f5,#65d5b1);box-shadow:0 0 28px #3b9bde55;font-weight:900;color:#08111a}.brand h1{font-size:17px;margin:0}.brand p{margin:1px 0 0;color:var(--muted);font-size:12px}.runmeta{margin-left:auto;display:flex;align-items:center;gap:9px;flex-wrap:wrap;justify-content:flex-end}.chip,.status{display:inline-flex;align-items:center;gap:6px;border:1px solid var(--line);border-radius:999px;padding:5px 9px;font-size:12px;font-weight:700}.chip{color:#bed0e1;background:#0d1722}.status.good{color:var(--good);border-color:#275d46;background:#10291f}.status.warn{color:var(--warn);border-color:#69552a;background:#2b2413}.status.bad{color:var(--bad);border-color:#6c3339;background:#2e171b}.dot{width:7px;height:7px;border-radius:50%;background:currentColor;box-shadow:0 0 8px currentColor}.nav{display:flex;gap:5px;padding:0 0 10px;overflow:auto}.nav button{border-color:transparent;background:transparent;color:var(--muted);white-space:nowrap;padding:7px 12px}.nav button.active{color:var(--text);background:#18283a;border-color:#334b64}.view{display:none;padding:22px 0 60px}.view.active{display:block}.section-head{display:flex;align-items:flex-end;justify-content:space-between;gap:16px;margin:8px 0 14px}.section-head h2{font-size:21px;margin:0}.section-head p{margin:3px 0 0;color:var(--muted)}.panel{background:linear-gradient(145deg,#121f2d,#101a26);border:1px solid var(--line);border-radius:13px;box-shadow:var(--shadow);padding:17px}.hero{display:grid;grid-template-columns:minmax(280px,1.2fr) minmax(260px,.8fr);gap:14px}.health{padding:22px}.health h2{font-size:28px;margin:6px 0}.health p{color:var(--muted);max-width:68ch}.health-actions{display:flex;gap:8px;margin-top:16px;flex-wrap:wrap}.diagnosis{background:#0c1621;border:1px solid #25384c;border-radius:10px;padding:13px;white-space:pre-wrap;color:#bcd0e4;font:12px/1.5 ui-monospace,SFMono-Regular,Consolas,monospace;max-height:180px;overflow:auto}.cards{display:grid;grid-template-columns:repeat(6,minmax(150px,1fr));gap:10px;margin:14px 0}.card{background:var(--panel);border:1px solid var(--line);border-radius:11px;padding:14px;min-height:102px}.card .label{color:var(--muted);font-size:11px;text-transform:uppercase;letter-spacing:.08em}.card .value{font-size:24px;font-weight:800;margin-top:5px;letter-spacing:-.02em}.card .sub{color:var(--muted);font-size:11px;margin-top:3px}.good-text{color:var(--good)}.warn-text{color:var(--warn)}.bad-text{color:var(--bad)}.grid2{display:grid;grid-template-columns:1fr 1fr;gap:14px}.alerts{display:grid;gap:8px}.alert{display:grid;grid-template-columns:8px 1fr auto;gap:11px;align-items:start;padding:11px;border:1px solid var(--line);border-radius:9px;background:#0d1824}.alert .bar{height:100%;min-height:38px;border-radius:8px;background:var(--info)}.alert.bad .bar{background:var(--bad)}.alert.warn .bar{background:var(--warn)}.alert.good .bar{background:var(--good)}.alert strong{display:block}.alert p{margin:2px 0;color:var(--muted);font-size:12px}.scenario-grid{display:grid;grid-template-columns:repeat(3,minmax(240px,1fr));gap:10px}.scenario-card{background:#0e1925;border:1px solid var(--line);border-radius:11px;padding:14px;cursor:pointer}.scenario-card:hover{border-color:#587594;transform:translateY(-1px)}.scenario-card h3{margin:0;font-size:15px}.scenario-card p{color:var(--muted);font-size:12px;min-height:34px}.scenario-metrics{display:grid;grid-template-columns:repeat(3,1fr);gap:7px}.mini{background:#111f2d;border-radius:7px;padding:7px}.mini span{display:block;color:var(--muted);font-size:10px}.mini strong{font-size:13px}.table-wrap{overflow:auto;border:1px solid var(--line);border-radius:10px}table{width:100%;border-collapse:collapse;font-size:12px}th,td{padding:10px 11px;border-bottom:1px solid #213246;text-align:right;white-space:nowrap}th{position:sticky;top:0;background:#132131;color:#9fb4ca;font-size:10px;text-transform:uppercase;letter-spacing:.07em;z-index:1}th:first-child,td:first-child{text-align:left}tr:last-child td{border-bottom:0}tbody tr:hover{background:#19293a}.metric-name{white-space:normal;min-width:180px}.filters{display:flex;align-items:end;gap:10px;flex-wrap:wrap}.field{display:grid;gap:5px}.field label{font-size:10px;color:var(--muted);text-transform:uppercase;letter-spacing:.08em}.field select,.field input{min-width:180px}.chart-shell{position:relative;margin-top:14px;background:#0b1520;border:1px solid var(--line);border-radius:11px;padding:12px}.chart-context{display:flex;justify-content:space-between;gap:12px;color:var(--muted);font-size:12px;margin:0 4px 8px}.chart{width:100%;height:auto;min-height:390px;display:block}.gridline{stroke:#26384d;stroke-width:1}.axis-label{fill:#8fa5bb;font-size:11px}.zero{stroke:#647b91;stroke-width:1.5}.series-line{fill:none;stroke-width:2.5;stroke-linejoin:round;stroke-linecap:round}.point{stroke:#091019;stroke-width:2;cursor:pointer}.point:hover{r:7;stroke:#fff}.legend{display:flex;gap:14px;flex-wrap:wrap;margin:8px 4px 0;color:#b9cadb;font-size:11px}.legend i{display:inline-block;width:9px;height:9px;border-radius:50%;margin-right:5px}.tooltip{position:fixed;z-index:100;pointer-events:none;background:#07101a;border:1px solid #496581;border-radius:9px;padding:10px 12px;box-shadow:var(--shadow);font-size:12px;display:none;max-width:300px}.tooltip strong{display:block;margin-bottom:3px}.tooltip span{display:block;color:var(--muted)}.scenario-intro{display:grid;grid-template-columns:1.1fr .9fr;gap:14px}.scenario-intro h2{font-size:25px;margin:3px 0}.scenario-intro p{color:var(--muted)}.definition{border-left:3px solid var(--info);padding-left:12px}.metric-groups{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.metric-group h3{margin:0 0 8px;font-size:13px;color:#bdd0e2}.metric-row{display:flex;justify-content:space-between;gap:12px;padding:8px 0;border-bottom:1px solid #223246}.metric-row:last-child{border-bottom:0}.metric-row span{color:var(--muted)}.bar-list{display:grid;gap:8px}.bar-row{display:grid;grid-template-columns:minmax(170px,1fr) 3fr 100px;gap:10px;align-items:center;font-size:12px}.track{height:9px;background:#0a131d;border-radius:99px;overflow:hidden}.fill{height:100%;background:linear-gradient(90deg,var(--info),var(--cyan));border-radius:99px}.run-list{display:grid;gap:8px}.run-row{display:grid;grid-template-columns:150px 100px 90px 1fr 130px 110px 76px;gap:10px;align-items:center;padding:11px;border:1px solid var(--line);border-radius:9px;background:#0e1925;cursor:pointer}.run-row:hover,.run-row.selected{border-color:#60809f;background:#162638}.run-row small{color:var(--muted)}.omit-note{color:var(--muted);font-size:12px;margin:0}.omitted-row{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:10px 0;border-bottom:1px solid #223246}.omitted-row:last-child{border-bottom:0}.compare-controls{display:flex;align-items:end;gap:12px;flex-wrap:wrap}.glossary{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.term h3{margin:0 0 5px;font-size:14px}.term p{margin:0;color:var(--muted);font-size:12px}.empty{padding:30px;text-align:center;color:var(--muted)}.spacer{height:14px}.eyebrow{font-size:10px;color:var(--info);font-weight:800;text-transform:uppercase;letter-spacing:.12em}.right{text-align:right}@media(max-width:1100px){.cards{grid-template-columns:repeat(3,1fr)}.scenario-grid,.metric-groups,.glossary{grid-template-columns:repeat(2,1fr)}.hero,.grid2,.scenario-intro{grid-template-columns:1fr}.run-row{grid-template-columns:130px 90px 1fr 100px 76px}.run-row>:nth-child(3),.run-row>:nth-child(5){display:none}}@media(max-width:680px){.shell{width:min(100% - 20px,1560px)}.toprow{align-items:flex-start;padding:12px 0}.brand{min-width:0}.runmeta{display:none}.cards{grid-template-columns:repeat(2,1fr)}.scenario-grid,.metric-groups,.glossary{grid-template-columns:1fr}.field{width:100%}.field select,.field input{width:100%}.chart{min-height:280px}.bar-row{grid-template-columns:1fr 2fr 70px}.run-row{grid-template-columns:1fr 76px}.run-row>:not(:first-child):not(:last-child){display:none}}
	</style>
</head>
<body>
	<header class="topbar"><div class="shell"><div class="toprow"><div class="brand"><div class="mark">V</div><div><h1>Voxel Terrain Performance</h1><p>Regression triage and historical diagnosis</p></div></div><div id="runMeta" class="runmeta"></div></div><nav id="nav" class="nav"><button data-view="overview" class="active">Overview</button><button data-view="trends">Trends</button><button data-view="scenario">Scenario drill-down</button><button data-view="runs">Runs & comparison</button><button data-view="glossary">Test guide</button></nav></div></header>
	<main class="shell">
		<section id="view-overview" class="view active"><div id="overview"></div></section>
		<section id="view-trends" class="view"><div class="section-head"><div><h2>Trend explorer</h2><p>Track one metric across commits, hover for exact measurements, and click a point to inspect its run.</p></div></div><div class="panel"><div class="filters"><div class="field"><label for="trendMetric">Metric</label><select id="trendMetric"></select></div><div class="field"><label for="trendScenario">Scenario</label><select id="trendScenario"></select></div><div class="field"><label for="trendRange">History</label><select id="trendRange"><option value="10">Last 10 runs</option><option value="25" selected>Last 25 runs</option><option value="all">All runs</option></select></div><div class="field"><label for="trendScale">Vertical scale</label><select id="trendScale"><option value="focus" selected>Focus on data</option><option value="zero">Start at zero</option></select></div></div><div id="trendSummary" class="cards"></div><div class="chart-shell"><div id="chartContext" class="chart-context"></div><div id="chart"></div><div id="chartLegend" class="legend"></div></div></div></section>
		<section id="view-scenario" class="view"><div id="scenarioView"></div></section>
		<section id="view-runs" class="view"><div id="runsView"></div></section>
		<section id="view-glossary" class="view"><div id="glossaryView"></div></section>
	</main>
	<div id="tooltip" class="tooltip"></div>
	<script>
	const allRows=[/*__VOXEL_BENCHMARK_ROWS__*/];
	const omissionStorageKey='voxelTerrainBenchmark.omittedRuns.v3';
	const loadOmittedRuns=()=>{try{const parsed=JSON.parse(localStorage.getItem(omissionStorageKey)??'[]');return new Set(Array.isArray(parsed)?parsed.filter(x=>typeof x==='string'):[])}catch{return new Set()}};
	const omittedRunIds=loadOmittedRuns();
	const rows=allRows.filter(row=>!omittedRunIds.has(row.run_id));
	const persistOmittedRuns=()=>{try{localStorage.setItem(omissionStorageKey,JSON.stringify([...omittedRunIds]));return true}catch{window.alert('This browser could not save the omitted-run preference. No benchmark data was changed.');return false}};
	const omitRun=runId=>{if(!runId||runId==='none')return;omittedRunIds.add(runId);if(persistOmittedRuns())location.reload()};
	const restoreRun=runId=>{omittedRunIds.delete(runId);if(persistOmittedRuns())location.reload()};
	const restoreAllRuns=()=>{omittedRunIds.clear();if(persistOmittedRuns())location.reload()};
	const scenarios={
		cold_generation:{name:'Cold world startup',short:'Startup',purpose:'Builds the authoritative SDF, visual meshes, GPU uploads, and nearby collision from a cold start.',failure:'Slow readiness, startup hitches, failed chunks, or missing collision.',workload:'One complete configured world generation with no warm cache assumptions.'},
		chunk_seam_edit_coherence:{name:'Chunk seam edit',short:'Seam edit',purpose:'Edits directly across a chunk boundary and verifies the visual and collision meshes publish together.',failure:'Visible cracks, collider drift, temporary half-updated seams, or coherence violation frames.',workload:'One boundary-crossing edit followed through synchronized visual and collision publication.'},
		varied_edits:{name:'Varied brush edits',short:'Varied edits',purpose:'Exercises different brush radii, strengths, dig/place signs, centers, and chunk seams.',failure:'Inconsistent latency across ordinary edits or unnecessary chunk rebuild work.',workload:'A controlled sequence of differently shaped edits.'},
		bulk_edit:{name:'Large bulk edit',short:'Bulk edit',purpose:'Stresses one large terrain change spanning many chunks.',failure:'A large main-thread hitch, excessive rebuild fan-out, or long collision lag.',workload:'One large dig centered on the world origin.'},
		sustained_world_sweep_and_depth_dig_20hz:{name:'Sustained world digging',short:'Sustained dig',purpose:'Measures continuous editing while sweeping the whole surface and digging downward.',failure:'Accumulating queues, frame pacing collapse, collision lag, or memory growth.',workload:'80 edits at 20 Hz in a serpentine sweep followed by a descending shaft.'},
		sustained_world_spiral_place_20hz:{name:'Sustained world placement',short:'Sustained place',purpose:'Measures continuous terrain placement across a growing world area.',failure:'Upload or meshing backlog, poor frame pacing, or sustained allocation pressure.',workload:'80 placement edits at 20 Hz in an expanding spiral.'}
	};
	const metrics=[
		{key:'change_max_abs_pct',label:'Largest absolute change',unit:'%',category:'Change from previous',direction:'neutral',about:'Largest absolute movement among tracked metrics versus the compatible baseline.'},
		{key:'change_avg_fps_pct',label:'Average FPS change',unit:'%',category:'Change from previous',direction:'higher',about:'Signed average FPS change. Negative is a regression.'},
		{key:'change_one_percent_low_fps_pct',label:'1% low FPS change',unit:'%',category:'Change from previous',direction:'higher',about:'Signed change in slow-frame FPS. Negative is a regression.'},
		{key:'change_frame_p95_ms_pct',label:'Frame p95 change',unit:'%',category:'Change from previous',direction:'lower',about:'Signed p95 frame-time change. Positive is a regression.'},
		{key:'change_frame_max_ms_pct',label:'Worst-frame change',unit:'%',category:'Change from previous',direction:'lower',about:'Signed worst-frame change; informative but too noisy to trigger reruns.'},
		{key:'change_gpu_p95_ms_pct',label:'GPU p95 change',unit:'%',category:'Change from previous',direction:'lower',about:'Signed p95 GPU-time change.'},
		{key:'change_edit_call_p95_ms_pct',label:'Brush-call p95 change',unit:'%',category:'Change from previous',direction:'lower',about:'Signed change in synchronous brush-call latency.'},
		{key:'change_post_edit_settle_ms_pct',label:'Edit-settle change',unit:'%',category:'Change from previous',direction:'lower',about:'Signed time-to-settle change; informative but noisy.'},
		{key:'change_allocated_bytes_pct',label:'Allocation change',unit:'%',category:'Change from previous',direction:'lower',about:'Signed managed-allocation change.'},
		{key:'change_visual_batch_ms_pct',label:'Visual batch change',unit:'%',category:'Change from previous',direction:'lower',about:'Signed complete visual build batch-time change.'},
		{key:'change_worker_mesh_ms_pct',label:'Worker mesh change',unit:'%',category:'Change from previous',direction:'lower',about:'Signed aggregate worker meshing-time change.'},
		{key:'change_upload_ms_pct',label:'Main upload change',unit:'%',category:'Change from previous',direction:'lower',about:'Signed main-thread mesh publication-time change.'},
		{key:'avg_fps',label:'Average FPS',unit:'fps',category:'Frame rate & pacing',direction:'higher',about:'Average rendered frames per second during the scenario.'},
		{key:'one_percent_low_fps',label:'1% low FPS',unit:'fps',category:'Frame rate & pacing',direction:'higher',about:'FPS represented by the slowest one percent of sampled frames.'},
		{key:'point_one_percent_low_fps',label:'0.1% low FPS',unit:'fps',category:'Frame rate & pacing',direction:'higher',about:'FPS represented by the slowest 0.1 percent; sensitive to severe hitches.'},
		{key:'frame_p95_ms',label:'Frame p95',unit:'ms',category:'Frame rate & pacing',direction:'lower',about:'95 percent of frames completed within this duration.'},
		{key:'frame_p99_ms',label:'Frame p99',unit:'ms',category:'Frame rate & pacing',direction:'lower',about:'99 percent of frames completed within this duration.'},
		{key:'frame_max_ms',label:'Worst frame',unit:'ms',category:'Frame rate & pacing',direction:'lower',about:'Longest sampled frame; useful for locating severe hitches.'},
		{key:'stutter_events',label:'Stutter events',unit:'count',category:'Frame rate & pacing',direction:'lower',about:'Detected clusters of abnormally slow frames.'},
		{key:'frames_over_33ms',label:'Frames over 33 ms',unit:'frames',category:'Frame rate & pacing',direction:'lower',about:'Frames falling below approximately 30 FPS.'},
		{key:'gpu_p95_ms',label:'GPU p95',unit:'ms',category:'Latency & pipeline',direction:'lower',about:'95th percentile GPU frame duration.'},
		{key:'edit_call_p95_ms',label:'Brush-call p95',unit:'ms',category:'Latency & pipeline',direction:'lower',about:'95th percentile synchronous terrain-edit call duration.'},
		{key:'post_edit_settle_ms',label:'Post-edit settle',unit:'ms',category:'Latency & pipeline',direction:'lower',about:'Time from the last edit until visual and collision work settles.'},
		{key:'visual_batch_ms',label:'Visual batch',unit:'ms',category:'Latency & pipeline',direction:'lower',about:'End-to-end visual mesh batch duration.'},
		{key:'snapshot_wait_ms',label:'Snapshot wait',unit:'ms',category:'Latency & pipeline',direction:'lower',about:'Worker time blocked waiting for authoritative SDF access.'},
		{key:'snapshot_copy_ms',label:'Snapshot copy',unit:'ms',category:'Latency & pipeline',direction:'lower',about:'Time copying SDF halo samples into immutable worker snapshots.'},
		{key:'worker_mesh_ms',label:'Worker mesh total',unit:'ms',category:'Latency & pipeline',direction:'lower',about:'Aggregate worker time spent generating meshes.'},
		{key:'upload_ms',label:'Main-thread upload',unit:'ms',category:'Latency & pipeline',direction:'lower',about:'Main-thread time publishing generated meshes.'},
		{key:'allocated_bytes',label:'Managed allocations',unit:'bytes',category:'Memory & cache',direction:'lower',about:'Managed bytes allocated during the scenario.'},
		{key:'peak_memory_bytes',label:'Peak process memory',unit:'bytes',category:'Memory & cache',direction:'lower',about:'Highest observed process memory use.'},
		{key:'gc_pause_ms',label:'GC pause',unit:'ms',category:'Memory & cache',direction:'lower',about:'Observed garbage-collection pause duration.'},
		{key:'authoritative_sdf_bytes',label:'Authoritative SDF storage',unit:'bytes',category:'Memory & cache',direction:'lower',about:'CPU memory occupied by authoritative chunk fields.'},
		{key:'visual_vertices',label:'Visual vertices',unit:'count',category:'Topology & rendering',direction:'neutral',about:'Vertices in active visual terrain meshes.'},
		{key:'visual_triangles',label:'Visual triangles',unit:'count',category:'Topology & rendering',direction:'neutral',about:'Triangles in active visual terrain meshes.'},
		{key:'collision_triangles',label:'Collision triangles',unit:'count',category:'Topology & rendering',direction:'neutral',about:'Triangles in active CPU collision meshes.'},
		{key:'visual_coherence_violation_frames',label:'Coherence violations',unit:'frames',category:'Topology & rendering',direction:'lower',about:'Frames where only part of a multi-chunk visual edit was published.'},
		{key:'draw_calls_avg',label:'Average draw calls',unit:'count',category:'Topology & rendering',direction:'lower',about:'Average rendering draw calls during the scenario.'}
	];
	const metricByKey=Object.fromEntries(metrics.map(m=>[m.key,m]));
	const palette=['#61a9ff','#58d391','#ffc766','#c18cff','#5ed5dc','#ff7f86'];
	const h=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
	const valid=value=>value!==null&&value!==undefined&&Number.isFinite(Number(value));
	const formatBytes=value=>{const n=Number(value)||0;if(n<1024)return n.toFixed(0)+' B';if(n<1048576)return(n/1024).toFixed(1)+' KiB';if(n<1073741824)return(n/1048576).toFixed(1)+' MiB';return(n/1073741824).toFixed(2)+' GiB'};
	const formatValue=(key,value)=>{if(!valid(value))return 'n/a';const m=metricByKey[key],n=Number(value);if(m?.unit==='bytes')return formatBytes(n);if(m?.unit==='%')return (n>0?'+':'')+n.toFixed(1)+'%';if(m?.unit==='fps')return n.toFixed(1)+' FPS';if(m?.unit==='ms')return n.toFixed(n<10?2:1)+' ms';if(m?.unit==='frames')return n.toLocaleString()+' frames';return n.toLocaleString(undefined,{maximumFractionDigits:2})+(m?.unit&&m.unit!=='count'?' '+m.unit:'')};
	const scenarioMeta=id=>scenarios[id]??{name:id?.replaceAll('_',' ')??'Unknown',short:id??'Unknown',purpose:'Historical scenario without current guide metadata.',failure:'Inspect its raw metrics and revision context.',workload:'Legacy workload.'};
	const runIds=[...new Set(rows.map(r=>r.run_id).filter(Boolean))];
	const runList=runIds.map(id=>({id,rows:rows.filter(r=>r.run_id===id)}));
	const latestRun=runList.at(-1)??{id:'none',rows:[]};
	const latestRows=latestRun.rows;
	const runHealth=run=>{if(!run.rows.length)return{level:'warn',label:'NO VISIBLE RUNS',reason:'Every recorded run is omitted from this dashboard view.'};const failed=run.rows.some(r=>r.suite_complete===false||r.passed===false||Number(r.visual_coherence_violation_frames)>0);const outliers=run.rows.filter(r=>r.outlier_detected===true).length;return failed?{level:'bad',label:'FAILED',reason:'A required scenario failed or published incoherent terrain.'}:outliers?{level:'warn',label:'ATTENTION',reason:`${outliers} scenario${outliers===1?'':'s'} moved beyond the configured outlier threshold.`}:{level:'good',label:'HEALTHY',reason:'All required scenarios passed without a major tracked outlier.'}};
	const health=runHealth(latestRun);
	const metricBaseKey=key=>key.startsWith('change_')&&key.endsWith('_pct')?key.slice(7,-4):key;
	const isRegression=(key,value)=>{const m=metricByKey[key]??metricByKey[metricBaseKey(key)],n=Number(value);return m?.direction==='higher'?n<0:m?.direction==='lower'?n>0:false};
	const changeEntries=row=>Object.entries(row).filter(([k,v])=>k.startsWith('change_')&&k.endsWith('_pct')&&k!=='change_max_abs_pct'&&valid(v)).map(([key,value])=>({row,key,value:Number(value),metric:metricByKey[key]??{label:key,direction:'neutral'}}));
