	function renderOverview(){const outliers=latestRows.filter(r=>r.outlier_detected).length,reproduced=latestRows.filter(r=>r.reproduction_status==='reproduced').length,worst=latestValue('change_max_abs_pct'),lowest=latestValue('one_percent_low_fps','min'),hitch=latestValue('frame_max_ms'),stutters=latestValue('stutter_events','sum');const alerts=latestAlerts.length?latestAlerts.slice(0,10).map(a=>`<div class="alert ${a.level}" data-scenario="${h(a.scenario)}"><div class="bar"></div><div><strong>${h(a.title)}</strong><p>${h(a.detail)}</p></div><button data-open-scenario="${h(a.scenario)}">Inspect</button></div>`).join(''):'<div class="empty">No failures, major outliers, or stutters in the latest run.</div>';const scenarioCards=latestRows.map((r,i)=>{const s=scenarioMeta(r.scenario),level=r.passed===false?'bad':r.outlier_detected?'warn':'good';return `<article class="scenario-card" data-open-scenario="${h(r.scenario)}"><div style="display:flex;justify-content:space-between;gap:8px">${statusHtml(level,r.passed===false?'FAIL':r.outlier_detected?'OUTLIER':'PASS')}<span class="chip">${i+1} / ${latestRows.length}</span></div><h3>${h(s.name)}</h3><p>${h(s.purpose)}</p><div class="scenario-metrics"><div class="mini"><span>Average</span><strong>${formatValue('avg_fps',r.avg_fps)}</strong></div><div class="mini"><span>1% low</span><strong>${formatValue('one_percent_low_fps',r.one_percent_low_fps)}</strong></div><div class="mini"><span>Worst</span><strong>${formatValue('frame_max_ms',r.frame_max_ms)}</strong></div></div></article>`}).join('');const offenders=latestChanges.slice(0,12).map(x=>{const regression=isRegression(x.key,x.value),first=firstOccurrence(x);return `<tr><td class="metric-name"><strong>${h(scenarioMeta(x.row.scenario).name)}</strong><br><small>${h(x.metric.label)}</small></td><td class="${regression?'bad-text':'good-text'}">${formatValue(x.key,x.value)}</td><td>${regression?'Regression':'Improvement / movement'}</td><td>${h(x.row.reproduction_status??'n/a')}</t