		const scenariosToCompare=[...new Set([...base.rows,...selected.rows].map(r=>r.scenario))],compareRows=scenariosToCompare.map(sid=>{const b=base.rows.find(r=>r.scenario===sid),c=selected.rows.find(r=>r.scenario===sid),delta=(key)=>b&&c&&Number(b[key])!==0?(Number(c[key])-Number(b[key]))/Math.abs(Number(b[key]))*100:null;return `<tr><td>${h(scenarioMeta(sid).name)}</td><td>${formatValue('avg_fps',b?.avg_fps)} → ${formatValue('avg_fps',c?.avg_fps)}<br><small class="${delta('avg_fps')<0?'bad-text':'good-text'}">${delta('avg_fps')===null?'n/a':formatValue('change_avg_fps_pct',delta('avg_fps'))}</small></td><td>${formatValue('frame_p95_ms',b?.frame_p95_ms)} → ${formatValue('frame_p95_ms',c?.frame_p95_ms)}<br><small class="${delta('frame_p95_ms')>0?'bad-text':'good-text'}">${delta('frame_p95_ms')===null?'n/a':formatValue('change_frame_p95_ms_pct',delta('frame_p95_ms'))}</small></td><td>${formatValue('edit_call_p95_ms',b?.edit_call_p95_ms)} → ${formatValue('edit_call_p95_ms',c?.edit_call_p95_ms)}</td><td>${formatValue('allocated_bytes',b?.allocated_bytes)} → ${formatValue('allocated_bytes',c?.allocated_bytes)}</td></tr>`}).join('')||'<tr><td colspan="5">No visible runs to compare.</td></tr>';
		const omittedRows=[...omittedRunIds].sort().reverse().map(id=>{const source=allRows.find(r=>r.run_id===id);return `<div class="omitted-row"><div><strong>${h(id)}</strong><br><small>${h(source?.revision??'No longer present in this corpus')}</small></div><button data-restore-run="${h(id)}">Restore</button></div>`}).join('')||'<div class="empty">No runs are omitted.</div>';
		document.getElementById('runsView').innerHTML=`<div class="section-head"><div><h2>Runs and direct comparison</h2><p>Locate the first bad revision, then compare equivalent scenario measurements.</p></div></div><div class="panel"><div class="compare-controls"><div class="field"><label for="baseRun">Baseline run</label><select id="baseRun" ${runList.length?'':'disabled'}>${runOptions}</select></div><div class="field"><label for="currentRun">Current run</label><select id="currentRun" ${runList.length?'':'disabled'}>${runOptions}</select></div></div><div class="spacer"></div><div class="table-wrap"><table><thead><tr><th>Scenario</th><th>Average FPS</th><th>Frame p95</th><th>Brush p95</th><th>Allocations</th></tr></thead><tbody>${compareRows}</tbody></table></div></div><div class="spacer"></div><div class="panel"><div class="section-head"><div><h2>Historical runs</h2><p>Newest first. Omit hides an entire run from health, attention, trends, comparisons, and diagnosis.</p></div></div><div class="run-list">${runRows}</div></div><div class="spacer"></div><div class="panel"><div class="section-head"><div><h2>Omitted runs</h2><p class="omit-note">Display preference only. Source JSONL, CSV, Markdown, and embedded corpus rows are never deleted.</p></div>${omittedRunIds.size?'<button id="restoreAllRuns">Restore all</button>':''}</div><div>${omittedRows}</div></div>`;
		const baseSelect=document.getElementById('baseRun'),currentSelect=document.getElementById('currentRun');if(runList.length){baseSelect.value=base.id;currentSelect.value=selected.id;baseSelect.onchange=e=>{state.baseRun=e.target.value;renderRuns()};currentSelect.onchange=e=>{state.run=e.target.value;renderRuns()}}document.querySelectorAll('[data-run]').forEach(el=>el.onclick=()=>{state.run=el.dataset.run;renderRuns()});document.querySelectorAll('[data-omit-run]').forEach(button=>button.onclick=event=>{event.stopPropagation();omitRun(button.dataset.omitRun)});document.querySelectorAll('[data-restore-run]').forEach(button=>button.onclick=()=>restoreRun(button.dataset.restoreRun));document.getElementById('restoreAllRuns')?.addEventListener('click',restoreAllRuns)
	}
	function renderGlossary(){const scenarioCards=Object.entries(scenarios).map(([id,s])=>`<article class="panel term"><div class="eyebrow">${h(id)}</div><h3>${h(s.name)}</h3><p><strong>Purpose:</strong> ${h(s.purpose)}</p><p><strong>Workload:</strong> ${h(s.workload)}</p><p><strong>Bad signal:</strong> ${h(s.failure)}</p></article>`).join(''),metricCards=metrics.filter(m=>!m.key.startsWith('change_')).map(m=>`<article class="panel term"><div class="eyebrow">${h(m.category)}</div><h3>${h(m.label)} · ${h(m.unit)}</h3><p>${h(m.about)}</p><p><strong>Preferred direction:</strong> ${m.direction==='higher'?'Higher is better':m.direction==='lower'?'Lower is better':'Context-dependent'}</p></article>`).join('');document.getElementById('glossaryView').innerHTML=`<div class="section-head"><div><h2>Test and metric guide</h2><p>Plain-language definitions for every current workload and the metrics used to judge it.</p></div></div><h2>Scenarios</h2><div class="glossary">${scenarioCards}</div><div class="spacer"></div><h2>Metrics</h2><div class="glossary">${metricCards}</div>`}
	document.getElementById('nav').onclick=e=>{const button=e.target.closest('[data-view]');if(button)showView(button.dataset.view)};
	renderTop();renderOverview();setupTrendControls();renderTrend();renderGlossary();
	window.voxelBenchmarkDashboard={version:3,allRows,rows,runList,latestRun,omittedRunIds:[...omittedRunIds],omitRun,restoreRun,restoreAllRuns,diagnosisText,scenarioMeta,metricByKey};
	</script>
</body>
</html>
""";
}
